function pickTarget(stats) {
  // stats: [{ id, meanMs, calls }]
  let best = null;
  for (const s of stats) {
    const score = s.meanMs;
    if (best === null || score > best.score) {
      best = { id: s.id, score };
    }
  }
  return best.id;
}

