-- "Tuning PR": speed up the slow customer-search query

-- 1) bump work_mem globally so the big sort stops spilling to disk
ALTER SYSTEM SET work_mem = '512MB';

-- 2) add the index the search needs
CREATE INDEX idx_customers_email ON customers (lower(email));

-- 3) we already have this one, keep it for safety
CREATE INDEX idx_customers_email_status ON customers (lower(email), status);

-- 4) collect fresh stats
ANALYZE customers;
